// Telegram Trigger emits the complete, secret-header-verified update.
// Authorization comes from the job's frozen approver IDs and chat in PostgreSQL.
const update = $input.first().json;
const callback = update.callback_query;
if (!callback || typeof callback.id !== 'string' || !callback.id) {
  throw new Error('Expected a full Telegram callback_query update');
}
function numericId(value, label) {
  if (typeof value === 'number' && !Number.isSafeInteger(value)) throw new Error(label + ' is not a safe integer');
  const id = String(value ?? '');
  if (!/^-?\d+$/.test(id)) throw new Error('Missing or invalid ' + label);
  return id;
}
const chatId = numericId(callback.message?.chat?.id, 'chat ID');
const userId = numericId(callback.from?.id, 'sender ID');
const messageId = numericId(callback.message?.message_id, 'message ID');
const match = /^([ar]):([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})$/.exec(String(callback.data ?? ''));
if (!match) throw new Error('Expected an approval or rejection button with a UUID token');
return [{json: {update, callbackId: callback.id, action: match[1], token: match[2], chatId, userId, messageId}}];
